def uploadFile(uploadfunc, fileindex, existing, uf, skip_broken=False):
    """Update a file object so that the location is a reference to the toil file
    store, writing it to the file store if necessary.

    """
    try:
        if existing[fileindex].file_size is None:
            raise ValueError("Cannot update the location of a file that has not been "
                             "written to the file store")
        if uf.location is None:
            # We can update the location in-place.
            uf.location = uploadfunc(existing[fileindex], uf.location)
        else:
            # We need to write the file to the file store.
            with uploadfunc(existing[fileindex], None) as (fileStoreID, size):
                # Update the file object in place.
                uf.location = fileStoreID
                uf.file_size = size
    except Exception:
        if not skip_broken:
            raise
        logger.warning("Skipping broken file: %s", uf)

